 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored diagonals form a periodic one-dimensional pattern. Choose
    # the diagonal orientation in which the observed colored stripes are most
    # complete; ties favor down-right diagonals.
    candidates = []
    for kind in (0, 1):  # 0: column-row; 1: row+column
        groups = {}
        total_lengths = {}
        for r in range(h):
            for c in range(w):
                k = c - r if kind == 0 else r + c
                total_lengths[k] = total_lengths.get(k, 0) + 1
                if grid[r][c] != 0:
                    groups.setdefault(k, grid[r][c])
        covered = sum(sum(1 for r in range(h) for c in range(w)
                          if (c-r if kind == 0 else r+c) == k)
                      for k in groups)
        colored = sum(1 for row in grid for v in row if v != 0)
        score = colored / covered if covered else 0
        candidates.append((score, kind, groups))
    _, kind, groups = max(candidates, key=lambda x: (x[0], -x[1]))
    period = len(groups)
    pattern = {}
    for k, value in groups.items():
        residue = k % period
        if residue in pattern and pattern[residue] != value:
            # Prefer the first observed stripe if a residue collides.
            continue
        pattern[residue] = value
    # All demonstrated patterns provide one seed for each residue.
    return [[pattern[(c-r if kind == 0 else r+c) % period]
             for c in range(w)] for r in range(h)]
"
}

